#!/usr/bin/env node
// Writes src/demo/recipes.js: the recipe XML files the in-app demo falls back to when the server is unreachable
// (or in ?mock=1 mode). Run `yarn bundle-recipes` after changing packages/server/src/recipes/*.xml.
const fs = require('fs')
const path = require('path')

const RECIPES = ['buns', 'tiramisu', 'negroni', 'tomato-soup']
const recipesDir = path.resolve(__dirname, '../../server/src/recipes')
const outFile = path.resolve(__dirname, '../src/demo/recipes.js')

const read = (name) => fs.readFileSync(path.join(recipesDir, `${name}.xml`), 'utf8')
const template = (text) => '`' + text.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${') + '`'
const titleOf = (xml, id) => {
  const m = xml.match(/<title>([^<]*)<\/title>/)
  return m ? m[1].trim() : id
}

const recipes = RECIPES.map((id) => ({ id, xml: read(id) }))
const lines = [
  '/* eslint-disable */',
  '// GENERATED by scripts/bundle-recipes.js from packages/server/src/recipes/*.xml — do not edit by hand.',
  '// Bundled copies of the recipes and the operation catalogue for the in-app demo (used in ?mock=1 mode or when the',
  '// server cannot be reached).',
  '',
  `export const OPERATIONS_XML = ${template(read('operations'))}`,
  '',
  'export const RECIPE_XML = {',
  ...recipes.map(({ id, xml }) => `  '${id}': ${template(xml)},`),
  '}',
  '',
  '/** The same shape as GET /api/recipes. */',
  'export const RECIPE_LIST = [',
  ...recipes.map(({ id, xml }) => `  { id: '${id}', title: ${JSON.stringify(titleOf(xml, id))} },`),
  ']',
  '',
]
fs.writeFileSync(outFile, lines.join('\n'))
console.log(`wrote ${path.relative(process.cwd(), outFile)} (${recipes.map((r) => r.id).join(', ')} + operations)`)
